// --- CÓDIGO PARA VERIFICAR A VALIDADE DO CUPOM (SEM LUXON) ---

// 1. Pega os dados do seu nó anterior.
const dadosDoCliente = $json;

// 2. Extrai as informações necessárias.
const ultimaInteracaoStr = dadosDoCliente.data_compra;
const diasDeValidade = parseInt(dadosDoCliente.validade_cupom, 10);

// 3. Prepara a variável de resultado.
let cupomEstaValido = false;

// 4. Executa a lógica apenas se houver uma data e dias de validade válidos.
if (ultimaInteracaoStr && !isNaN(diasDeValidade) && diasDeValidade > 0) {

// --- INÍCIO DA CORREÇÃO ---
// Converte a string da última interação em um objeto de Data nativo do JavaScript.
const dataUltimaInteracao = new Date(ultimaInteracaoStr);

// Calcula a data de expiração.
// 'new Date(dataUltimaInteracao)' cria uma cópia para não modificar a original.
const dataExpiracao = new Date(dataUltimaInteracao);
dataExpiracao.setDate(dataExpiracao.getDate() + diasDeValidade);

// Pega a data e hora atuais.
const agora = new Date();

// Compara se a data atual é ANTERIOR ou IGUAL à data de expiração.
if (agora <= dataExpiracao) {
cupomEstaValido = true;
}
// --- FIM DA CORREÇÃO ---

}

// 5. Adiciona o resultado (true ou false) ao item.
$json.cupomValido = cupomEstaValido;

// Retorna o item com a nova propriedade.
return $json;
